
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_rcam_b3lyp_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_rcam_b3lyp", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.428422378861174e+00, -3.361543364050366e+00, -3.267875173750262e+00, -3.138213324804112e+00, -2.961714388292018e+00, -2.727151653487306e+00, -2.425828781740612e+00, -2.056576319891204e+00, -1.631412164035877e+00, -1.174942238064337e+00, -7.181246412439956e-01, -4.417005905200947e-01, -3.659126467475948e-01, -2.769231417249214e-01, -1.561887803843396e-01, -4.328557211335401e-02, 7.510553176752218e-03, 2.459652066792102e-03, 5.820985608985571e-04, -1.818490741532748e-05]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


